CREATE OR REPLACE FUNCTION private.apply_task_item_operation_v2(p_operation_id uuid, p_task_item_id uuid, p_expected_version bigint, p_kind text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := private.require_auth();
    v_claimed boolean;
    v_saved jsonb;
    v_task_id uuid;
    v_project_id uuid;
    v_project public.projects%rowtype;
    v_task public.tasks%rowtype;
    v_role public.project_role;
    v_item public.task_items%rowtype;
    v_result jsonb;
begin
    if p_expected_version is null or p_expected_version < 1 then
        raise exception 'expected_version is required' using errcode = '22023';
    end if;
    if p_kind not in ('set_task_item_state', 'set_task_item_percentage', 'set_task_item_comment') then
        raise exception 'invalid operation type' using errcode = '22023';
    end if;
    select claimed, saved_result into v_claimed, v_saved
      from private.claim_client_operation(p_operation_id, p_kind || '_v2', p_task_item_id, p_payload);
    if not v_claimed then return v_saved; end if;

    select task_id into v_task_id from public.task_items where id = p_task_item_id;
    if not found then raise exception 'task item not found' using errcode = '42501'; end if;
    v_project_id := private.task_project_id(v_task_id);
    if v_project_id is null then raise exception 'task not found' using errcode = '42501'; end if;
    v_project := private.lock_project_state(v_project_id);
    v_task := private.lock_task(v_task_id);
    v_role := private.lock_task_role(v_task_id, v_project_id, v_user);
    select * into v_item from public.task_items where id = p_task_item_id for update;
    if not found or v_item.task_id <> v_task_id or v_role is null
       or v_role not in ('owner', 'admin', 'member') then
        raise exception 'no access to task item' using errcode = '42501';
    end if;
    if v_item.is_archived or v_task.status = 'archived' or v_project.status <> 'active' then
        raise exception 'task item is archived' using errcode = '42501';
    end if;
    if v_item.sync_version <> p_expected_version then
        delete from private.client_operation_receipts
         where user_id = v_user and operation_id = p_operation_id;
        return pg_catalog.jsonb_build_object('status', 'conflict', 'version', v_item.sync_version,
            'item', pg_catalog.to_jsonb(v_item));
    end if;

    if p_kind = 'set_task_item_state' then
        perform public.set_task_item_state(p_task_item_id, (p_payload ->> 'completed')::boolean);
    elsif p_kind = 'set_task_item_percentage' then
        perform public.set_task_item_percentage(p_task_item_id, (p_payload ->> 'percentage')::integer);
    else
        perform public.set_task_item_comment(p_task_item_id, p_payload ->> 'comment');
    end if;
    select * into v_item from public.task_items where id = p_task_item_id;
    -- An accepted semantic no-op still advances the protocol version so the
    -- next queued operation always has a fresh, unambiguous precondition.
    if v_item.sync_version = p_expected_version then
        perform pg_catalog.set_config('tasktrace.force_sync_version_bump', 'on', true);
        update public.task_items set sync_version = sync_version where id = p_task_item_id;
        perform pg_catalog.set_config('tasktrace.force_sync_version_bump', 'off', true);
        select * into v_item from public.task_items where id = p_task_item_id;
    end if;
    v_result := pg_catalog.jsonb_build_object('status', 'applied', 'version', v_item.sync_version,
        'item', pg_catalog.to_jsonb(v_item));
    update private.client_operation_receipts
       set result_payload = v_result, completed_at = now()
     where user_id = v_user and operation_id = p_operation_id;
    return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.audit_log_visible(p_project_id uuid, p_entity_type text, p_entity_id uuid, p_old_data jsonb, p_new_data jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_task_id uuid;
    v_template_id uuid;
begin
    if p_entity_type = 'profile' then
        return p_entity_id = auth.uid();
    end if;

    if p_entity_type = 'task_template' then
        return exists (
            select 1
              from public.task_templates tt
             where tt.id = p_entity_id
               and tt.created_by = auth.uid()
        ) or coalesce(p_new_data->>'created_by', p_old_data->>'created_by') = auth.uid()::text;
    end if;

    if p_entity_type = 'task_template_item' then
        select tti.template_id
          into v_template_id
          from public.task_template_items tti
         where tti.id = p_entity_id;
        if v_template_id is null then
            begin
                v_template_id := nullif(coalesce(p_new_data->>'template_id', p_old_data->>'template_id'), '')::uuid;
            exception when invalid_text_representation then
                return false;
            end;
        end if;
        return exists (
            select 1
              from public.task_templates tt
             where tt.id = v_template_id
               and tt.created_by = auth.uid()
        );
    end if;

    if p_project_id is not null and private.is_project_admin(p_project_id) then
        return true;
    end if;

    if p_entity_type in ('project', 'project_member') then
        return p_project_id is not null and private.is_project_member(p_project_id);
    end if;

    if p_entity_type in ('task', 'task_from_template') then
        return p_entity_id is not null
           and private.task_project_id(p_entity_id) = p_project_id
           and private.has_task_access(p_entity_id);
    end if;

    if p_entity_type = 'task_item' then
        return exists (
            select 1
              from public.task_items ti
             where ti.id = p_entity_id
               and private.task_project_id(ti.task_id) = p_project_id
               and private.has_task_access(ti.task_id)
        );
    end if;

    if p_entity_type in ('task_member', 'task_assignee') then
        begin
            v_task_id := nullif(coalesce(p_new_data->>'task_id', p_old_data->>'task_id'), '')::uuid;
        exception when invalid_text_representation then
            return false;
        end;
        return v_task_id is not null
           and private.task_project_id(v_task_id) = p_project_id
           and private.has_task_access(v_task_id);
    end if;

    return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.audit_to_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_task_id uuid;
    v_type public.notification_type;
    v_title text;
    v_body text;
    v_recipient uuid;
    v_project_name text;
    v_task_title text;
    v_item_title text;
    v_person_name text;
    v_change_summary text;
    v_role_label text;
    v_actor uuid := coalesce(new.user_id, '00000000-0000-0000-0000-000000000000'::uuid);
begin
    if new.action = 'role_changed' and new.entity_type = 'task_member' then
        v_type := 'task_role_changed';
        v_recipient := new.entity_id;
        v_task_id := nullif(new.new_data->>'task_id', '')::uuid;
        v_title := 'Права чек-листа изменены';
    elsif new.action = 'assignee_added' then
        v_type := 'task_assigned';
        v_recipient := new.entity_id;
        v_task_id := nullif(new.new_data->>'task_id', '')::uuid;
        v_title := 'Вас назначили исполнителем';
    elsif new.action = 'assignee_removed' then
        v_type := 'task_unassigned';
        v_recipient := new.entity_id;
        v_task_id := nullif(new.new_data->>'task_id', '')::uuid;
        v_title := 'Назначение снято';
    elsif new.action in ('checked', 'unchecked') then
        v_type := case when new.action = 'checked'
                       then 'task_item_checked' else 'task_item_unchecked' end;
        v_title := case when new.action = 'checked'
                        then 'Пункт отмечен' else 'Отметка пункта снята' end;
        select task_id, title into v_task_id, v_item_title
          from public.task_items where id = new.entity_id;
    elsif new.action = 'updated'
      and new.entity_type = 'task_item'
      and (new.new_data ? 'title'
        or new.new_data ? 'description'
        or new.new_data ? 'position'
        or new.new_data ? 'percentage'
        or new.new_data ? 'comment'
        or new.new_data ? 'is_completed') then
        v_type := 'task_item_changed';
        v_title := 'Изменён пункт чек-листа';
        select task_id, title into v_task_id, v_item_title
          from public.task_items where id = new.entity_id;
    elsif new.action = 'archived' and new.entity_type = 'project' then
        v_type := 'project_archived';
        v_title := 'Проект архивирован';
    elsif new.action = 'restored' and new.entity_type = 'project' then
        v_type := 'project_restored';
        v_title := 'Проект восстановлен';
    elsif new.action = 'archived' and new.entity_type = 'task' then
        v_type := 'task_archived';
        v_task_id := new.entity_id;
        v_title := 'Этап архивирован';
    elsif new.action = 'restored' and new.entity_type = 'task' then
        v_type := 'task_restored';
        v_task_id := new.entity_id;
        v_title := 'Этап восстановлен';
    else
        return new;
    end if;

    if new.entity_type = 'project' and new.action in ('archived', 'restored') then
        select name into v_project_name from public.projects where id = new.project_id;
        v_body := format(
            'Проект «%s» %s.',
            coalesce(v_project_name, 'Без названия'),
            case when new.action = 'archived' then 'архивирован' else 'восстановлен' end
        );
        for v_recipient in
            select pm.user_id
              from public.project_members pm
             where pm.project_id = new.project_id and pm.user_id <> v_actor
        loop
            perform private.create_notification(
                v_recipient,
                new.project_id,
                null,
                v_type,
                v_title,
                v_body,
                jsonb_build_object('project_id', new.project_id),
                'audit:' || new.id::text
            );
        end loop;
        return new;
    end if;

    if v_task_id is null then return new; end if;
    select p.name, t.title
      into v_project_name, v_task_title
      from public.tasks t
      join public.projects p on p.id = t.project_id
     where t.id = v_task_id;
    v_project_name := coalesce(v_project_name, 'Без названия');
    v_task_title := coalesce(v_task_title, 'Без названия');

    if new.action in ('archived', 'restored') and new.entity_type = 'task' then
        v_body := format(
            'Этап «%s» в проекте «%s» %s.',
            v_task_title,
            v_project_name,
            case when new.action = 'archived' then 'архивирован' else 'восстановлен' end
        );
        for v_recipient in
            select pm.user_id
              from public.project_members pm
             where pm.project_id = new.project_id and pm.user_id <> v_actor
        loop
            perform private.create_notification(
                v_recipient,
                new.project_id,
                v_task_id,
                v_type,
                v_title,
                v_body,
                jsonb_build_object('task_id', v_task_id),
                'audit:' || new.id::text
            );
        end loop;
        return new;
    end if;

    if new.action = 'role_changed' and new.entity_type = 'task_member' then
        if new.new_data->>'role_override' is null then
            v_body := format(
                'Права чек-листа этапа «%s» снова наследуются от роли в проекте «%s».',
                v_task_title,
                v_project_name
            );
        else
            v_role_label := case new.new_data->>'role_override'
                when 'admin' then 'Администратор чек-листа'
                when 'member' then 'Участник'
                when 'viewer' then 'Только просмотр'
                else new.new_data->>'role_override'
            end;
            v_body := format(
                'Для чек-листа этапа «%s» в проекте «%s» установлена роль «%s».',
                v_task_title,
                v_project_name,
                v_role_label
            );
        end if;
    elsif new.action = 'assignee_added' then
        v_body := format(
            'Вы назначены исполнителем этапа «%s» в проекте «%s».',
            v_task_title,
            v_project_name
        );
    elsif new.action = 'assignee_removed' then
        v_body := format(
            'С вас снято назначение на этапе «%s» проекта «%s».',
            v_task_title,
            v_project_name
        );
    elsif new.action in ('checked', 'unchecked') then
        v_body := format(
            '«%s» → этап «%s» → проект «%s».',
            coalesce(v_item_title, 'Пункт чек-листа'),
            v_task_title,
            v_project_name
        );
    else
        v_change_summary := concat_ws(', ',
            case when new.new_data ? 'title' then 'название' end,
            case when new.new_data ? 'description' then 'описание' end,
            case when new.new_data ? 'position' then 'порядок' end,
            case when new.new_data ? 'percentage'
                 then format('прогресс %s%%', new.new_data->>'percentage') end,
            case when new.new_data ? 'comment' then 'комментарий' end,
            case when new.new_data ? 'is_completed'
                       and not (new.new_data ? 'percentage') then 'состояние' end
        );
        v_body := format(
            'Пункт «%s» изменён (%s) на этапе «%s» проекта «%s».',
            coalesce(v_item_title, 'Пункт чек-листа'),
            coalesce(v_change_summary, 'данные'),
            v_task_title,
            v_project_name
        );
    end if;

    if new.action in ('checked', 'unchecked', 'updated') then
        for v_recipient in
            select pm.user_id
              from public.project_members pm
             where pm.project_id = new.project_id
               and pm.user_id <> v_actor
               and private.has_task_access(v_task_id, pm.user_id)
        loop
            perform private.create_notification(
                v_recipient,
                new.project_id,
                v_task_id,
                v_type,
                v_title,
                v_body,
                jsonb_build_object('task_id', v_task_id, 'entity_id', new.entity_id),
                'audit:' || new.id::text
            );
        end loop;
    elsif v_recipient is not null and v_recipient <> v_actor then
        perform private.create_notification(
            v_recipient,
            new.project_id,
            v_task_id,
            v_type,
            v_title,
            v_body,
            jsonb_build_object('task_id', v_task_id),
            'audit:' || new.id::text
        );
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.broadcast_application_invalidation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
    v_project_id uuid;
    v_task_id uuid;
    v_user_id uuid;
    v_recipient uuid;
    v_payload jsonb := jsonb_build_object('table', tg_table_name, 'operation', tg_op);
begin
    if tg_table_name = 'projects' then
        v_project_id := nullif(v_row->>'id', '')::uuid;
    elsif tg_table_name = 'project_members' then
        v_project_id := nullif(v_row->>'project_id', '')::uuid;
        v_user_id := nullif(v_row->>'user_id', '')::uuid;
    elsif tg_table_name = 'tasks' then
        v_project_id := nullif(v_row->>'project_id', '')::uuid;
        v_task_id := nullif(v_row->>'id', '')::uuid;
    elsif tg_table_name = 'task_items' then
        v_task_id := nullif(v_row->>'task_id', '')::uuid;
        select t.project_id into v_project_id
          from public.tasks t where t.id = v_task_id;
    elsif tg_table_name in ('task_members', 'task_assignees') then
        v_task_id := nullif(v_row->>'task_id', '')::uuid;
        v_user_id := nullif(v_row->>'user_id', '')::uuid;
        select t.project_id into v_project_id
          from public.tasks t where t.id = v_task_id;
    elsif tg_table_name = 'notifications' then
        v_user_id := nullif(v_row->>'user_id', '')::uuid;
    else
        return null;
    end if;

    if v_project_id is not null then
        perform realtime.send(v_payload, 'invalidate', 'project:' || v_project_id::text, true);
    end if;
    if v_task_id is not null then
        perform realtime.send(v_payload, 'invalidate', 'task:' || v_task_id::text, true);
    end if;
    if v_user_id is not null then
        perform realtime.send(v_payload, 'invalidate', 'user:' || v_user_id::text, true);
    end if;
    if tg_table_name = 'projects' and v_project_id is not null and tg_op <> 'DELETE' then
        for v_recipient in
            select pm.user_id
              from public.project_members pm
             where pm.project_id = v_project_id
               and pm.user_id is distinct from v_user_id
        loop
            perform realtime.send(v_payload, 'invalidate', 'user:' || v_recipient::text, true);
        end loop;
    elsif tg_table_name in ('tasks', 'task_items') and v_task_id is not null then
        for v_recipient in
            select pm.user_id
              from public.project_members pm
             where pm.project_id = v_project_id
               and private.has_task_access(v_task_id, pm.user_id)
               and pm.user_id is distinct from v_user_id
        loop
            perform realtime.send(v_payload, 'invalidate', 'user:' || v_recipient::text, true);
        end loop;
    end if;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.can_receive_realtime_topic(p_topic text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_user uuid := auth.uid();
    v_kind text := split_part(p_topic, ':', 1);
    v_value text := split_part(p_topic, ':', 2);
    v_id uuid;
begin
    if v_user is null
       or p_topic <> (v_kind || ':' || v_value)
       or v_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        return false;
    end if;
    v_id := v_value::uuid;

    if v_kind = 'user' then
        return v_id = v_user;
    elsif v_kind = 'project' then
        return private.is_project_member(v_id, v_user);
    elsif v_kind = 'task' then
        return private.has_task_access(v_id, v_user);
    end if;
    return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.checklist_deadline_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if tg_op = 'INSERT' and new.deadline_at is null then return new; end if;
    if tg_op = 'UPDATE' and new.deadline_at is null and old.deadline_at is null then return new; end if;
    insert into private.checklist_deadline_state(item_id) values (new.id) on conflict do nothing;
    -- Lock before emitting or comparing so concurrent cron workers cannot
    -- observe half of a deadline change. No scheduled payload survives a move.
    perform 1 from private.checklist_deadline_state where item_id = new.id for update;
    if tg_op = 'INSERT' or new.deadline_at is distinct from old.deadline_at then
      update private.checklist_deadline_state set state = 'normal' where item_id = new.id;
      perform private.emit_checklist_deadline_event(new.id,
        case when new.deadline_at is null then 'removed' when tg_op = 'INSERT' or old.deadline_at is null then 'set' else 'changed' end,
        case when tg_op = 'UPDATE' then old.deadline_at else null end, auth.uid());
    end if;
    perform private.refresh_checklist_deadline(new.id, pg_catalog.now(), auth.uid());
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_client_operation(p_operation_id uuid, p_operation_type text, p_task_item_id uuid, p_request_payload jsonb)
 RETURNS TABLE(claimed boolean, saved_result jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := private.require_auth();
    v_receipt private.client_operation_receipts%rowtype;
    v_claim_count integer;
begin
    if p_operation_id is null or p_task_item_id is null then
        raise exception 'operation id and task item id are required' using errcode = '22023';
    end if;
    insert into private.client_operation_receipts
        (user_id, operation_id, operation_type, task_item_id, request_payload)
    values (v_user, p_operation_id, p_operation_type, p_task_item_id, p_request_payload)
    on conflict (user_id, operation_id) do nothing;
    get diagnostics v_claim_count = row_count;
    if v_claim_count > 0 then
        return query select true, null::jsonb;
        return;
    end if;

    select * into v_receipt
      from private.client_operation_receipts
     where user_id = v_user and operation_id = p_operation_id;
    if not found then
        raise exception 'operation receipt unavailable' using errcode = '40001';
    end if;
    if v_receipt.operation_type is distinct from p_operation_type
       or v_receipt.task_item_id is distinct from p_task_item_id
       or v_receipt.request_payload is distinct from p_request_payload then
        raise exception 'operation_id reused with different request' using errcode = '22023';
    end if;
    if v_receipt.completed_at is null then
        raise exception 'operation receipt incomplete' using errcode = '40001';
    end if;
    return query select false, v_receipt.result_payload;
end;
$function$

CREATE OR REPLACE FUNCTION private.cleanup_task_item_sync_changes()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_floor bigint;
begin
    -- Same lock as the Phase 5 item statement trigger: no feed insert can race
    -- with advancing the floor in this transaction.
    perform pg_catalog.pg_advisory_xact_lock(29175, 5);
    with removed as (
        delete from private.task_item_sync_changes
         where created_at < pg_catalog.now() - interval '90 days'
         returning cursor
    ) select max(cursor) into v_floor from removed;
    if v_floor is not null then
        update private.task_item_sync_retention
           set retained_after_cursor = greatest(retained_after_cursor, v_floor),
               updated_at = pg_catalog.now()
         where singleton;
    end if;
    return (select retained_after_cursor from private.task_item_sync_retention where singleton);
end;
$function$

CREATE OR REPLACE FUNCTION private.emit_checklist_deadline_event(p_item_id uuid, p_event text, p_previous_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_item public.task_items%rowtype;
    v_project uuid;
    v_project_name text;
    v_task_name text;
    v_number bigint;
    v_audit bigint;
    v_title text;
    v_data jsonb;
    v_recipient uuid;
begin
    select * into v_item from public.task_items where id = p_item_id;
    if not found then return; end if;
    select t.project_id, t.title, p.name into v_project, v_task_name, v_project_name
      from public.tasks t join public.projects p on p.id = t.project_id where t.id = v_item.task_id;
    update private.checklist_deadline_state set event_number = event_number + 1
      where item_id = p_item_id returning event_number into v_number;
    v_title := case p_event
      when 'set' then 'Установлен дедлайн'
      when 'changed' then 'Дедлайн изменён'
      when 'removed' then 'Дедлайн удалён'
      when 'urgent' then 'Горящий дедлайн'
      when 'overdue' then 'Просрочен дедлайн'
      when 'completed' then 'Чек-лист с предупреждением выполнен'
      when 'reopened_urgent' then 'Снова горящий дедлайн'
      when 'reopened_overdue' then 'Снова просрочен дедлайн'
      else 'Состояние дедлайна изменено' end;
    v_data := pg_catalog.jsonb_build_object('task_id', v_item.task_id,
      'entity_id', p_item_id, 'item_id', p_item_id, 'deadline_event', p_event,
      'deadline_at', v_item.deadline_at, 'previous_deadline_at', p_previous_deadline,
      'title', v_item.title, 'task_title', v_task_name, 'project_name', v_project_name,
      'event_number', v_number);
    -- The existing generic audit notifier ignores this entity type; the
    -- deadline event owns its single notification fanout below.
    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, old_data, new_data)
      values (v_project, p_actor, 'updated', 'task_item_deadline', p_item_id,
        pg_catalog.jsonb_build_object('deadline_at', p_previous_deadline), v_data)
      returning id into v_audit;
    for v_recipient in select pm.user_id from public.project_members pm
      where pm.project_id = v_project and private.has_task_access(v_item.task_id, pm.user_id)
    loop
      perform private.create_notification(v_recipient, v_project, v_item.task_id, 'task_item_changed',
        v_title, pg_catalog.format('Чек-лист «%s» → этап «%s» → проект «%s». %s',
          v_item.title, v_task_name, v_project_name,
          case when v_item.deadline_at is null then 'Дедлайн удалён.'
            else 'Срок: ' || pg_catalog.to_char(v_item.deadline_at at time zone 'UTC', 'DD.MM.YYYY HH24:MI') || ' UTC.' end),
        v_data, 'deadline:audit:' || v_audit::text);
    end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_profile(p_user_id uuid)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public', 'auth'
AS $function$
declare
    v_profile public.profiles%rowtype;
    v_user auth.users%rowtype;
begin
    select * into v_profile from public.profiles where id = p_user_id;
    if found then
        return v_profile;
    end if;

    select * into v_user from auth.users where id = p_user_id;
    if not found then
        raise exception 'auth user not found' using errcode = 'insufficient_privilege';
    end if;

    insert into public.profiles(id, display_name)
    values (
        v_user.id,
        private.initial_profile_name(v_user.id, coalesce(v_user.raw_user_meta_data, '{}'::jsonb), v_user.email)
    )
    on conflict (id) do nothing;

    select * into v_profile from public.profiles where id = p_user_id;
    return v_profile;
end;
$function$

CREATE OR REPLACE FUNCTION private.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
begin
    insert into public.profiles(id, display_name)
    values (
        new.id,
        private.initial_profile_name(new.id, coalesce(new.raw_user_meta_data, '{}'::jsonb), new.email)
    )
    on conflict (id) do nothing;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.initial_profile_name(p_user_id uuid, p_metadata jsonb, p_email text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'private'
AS $function$
declare
    v_candidate text;
begin
    foreach v_candidate in array array[
        nullif(btrim(p_metadata->>'display_name'), ''),
        nullif(btrim(p_metadata->>'name'), ''),
        nullif(btrim(split_part(coalesce(p_email, ''), '@', 1)), '')
    ] loop
        if private.profile_name_is_valid(v_candidate) then
            return btrim(v_candidate);
        end if;
    end loop;
    return 'user-' || left(p_user_id::text, 8);
end;
$function$

CREATE OR REPLACE FUNCTION private.lock_task_role(p_task_id uuid, p_project_id uuid, p_user_id uuid)
 RETURNS project_role
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_project_role public.project_role;
    v_override public.project_role;
begin
    v_project_role := private.lock_project_role(p_project_id, p_user_id);
    if v_project_role is null then return null; end if;

    select role_override into v_override
      from public.task_members
     where task_id = p_task_id and user_id = p_user_id
     for update;
    return coalesce(v_override, v_project_role);
end;
$function$

CREATE OR REPLACE FUNCTION private.normalize_stage_notification_terminology()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
begin
    if new.task_id is null then
        return new;
    end if;

    new.title := replace(new.title, 'Доступ к задаче', 'Доступ к этапу');
    new.title := replace(new.title, 'Задача архивирована', 'Этап архивирован');
    new.title := replace(new.title, 'Задача восстановлена', 'Этап восстановлен');

    new.body := replace(new.body, 'доступ к задаче', 'доступ к этапу');
    new.body := replace(new.body, 'Вас добавили в задачу', 'Вас добавили в этап');
    new.body := replace(new.body, 'Ваш доступ к задаче был отозван', 'Ваш доступ к этапу был отозван');
    new.body := replace(new.body, 'назначили ответственным за задачу', 'назначили ответственным за этап');
    new.body := replace(new.body, 'назначены исполнителем задачи', 'назначены исполнителем этапа');
    new.body := replace(new.body, 'назначение в задаче', 'назначение на этапе');
    new.body := replace(new.body, '→ задача «', '→ этап «');
    new.body := replace(new.body, 'в задаче «', 'на этапе «');
    new.body := replace(new.body, 'Задача «', 'Этап «');

    return new;
end
$function$

CREATE OR REPLACE FUNCTION private.offline_account_rows(p_dataset text, p_snapshot_at timestamp with time zone)
 RETURNS TABLE(row_key text, row_data jsonb)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  case p_dataset
  when 'profile' then
    return query select p.id::text, to_jsonb(p) from public.profiles p where p.id = auth.uid();
  when 'projects' then
    return query select p.id::text, to_jsonb(p) || jsonb_build_object('role', m.role)
      from public.projects p join public.project_members m on m.project_id = p.id and m.user_id = auth.uid();
  when 'members' then
    return query select m.project_id::text || ':' || m.user_id::text, to_jsonb(m) from public.project_members m;
  when 'profiles' then
    return query select p.id::text, to_jsonb(p) from public.profiles p
      where p.id = auth.uid() or exists (select 1 from public.project_members m where m.user_id = p.id)
        or exists (select 1 from public.task_assignees a where a.user_id = p.id);
  when 'tasks' then
    return query select t.id::text, to_jsonb(t) from public.tasks t;
  when 'roles' then
    return query select t.id::text, jsonb_build_object('task_id', t.id, 'role', public.get_my_task_role(t.id)) from public.tasks t;
  when 'overrides' then
    return query select m.task_id::text || ':' || m.user_id::text,
      jsonb_build_object('task_id', m.task_id, 'user_id', m.user_id, 'role_override', m.role_override, 'set_by', m.set_by, 'set_at', m.set_at)
      from public.task_members m join public.tasks t on t.id = m.task_id
      join public.project_members pm on pm.project_id = t.project_id and pm.user_id = auth.uid()
      where pm.role in ('owner', 'admin') and m.role_override is not null;
  when 'assignees' then
    return query select a.task_id::text || ':' || a.user_id::text, to_jsonb(a) from public.task_assignees a;
  when 'items' then
    return query select i.id::text, to_jsonb(i) from public.task_items i;
  when 'templates' then
    return query select t.id::text, to_jsonb(t) from public.list_task_templates() t;
  when 'template_items' then
    return query select i.id::text, to_jsonb(i) || jsonb_build_object('position', i.template_position)
      from public.list_task_templates() t cross join lateral public.list_task_template_items(t.id) i;
  when 'daily_audit' then
    return query select lpad(a.id::text, 20, '0'), to_jsonb(a) from public.audit_log a
      where a.entity_type = 'task_item'
        and a.created_at >= date_trunc('day', p_snapshot_at at time zone 'Etc/GMT-3') at time zone 'Etc/GMT-3'
        and a.created_at <= p_snapshot_at;
  when 'history' then
    return query select lpad(a.id::text, 20, '0'), to_jsonb(a) from public.audit_log a
      where a.project_id is not null and a.created_at >= p_snapshot_at - interval '90 days'
        and a.created_at <= p_snapshot_at;
  when 'notifications' then
    return query select n.id::text, to_jsonb(n) from public.notifications n where n.user_id = auth.uid() and n.created_at <= p_snapshot_at and
      (not n.is_read or n.id in (select r.id from public.notifications r where r.user_id = auth.uid() and r.is_read and r.created_at <= p_snapshot_at
        order by r.created_at desc, r.id desc limit 100));
  when 'last_editors' then
    return query select e.task_item_id::text, to_jsonb(e) || jsonb_build_object('task_id', t.id)
      from public.tasks t cross join lateral public.list_task_item_last_editors(t.id) e;
  else raise exception 'unknown offline dataset' using errcode = '22023';
  end case;
end $function$

CREATE OR REPLACE FUNCTION private.process_checklist_deadlines(p_limit integer DEFAULT 1000)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row record; v_count integer := 0;
begin
    for v_row in select s.item_id, t.id as task_id, t.project_id
      from private.checklist_deadline_state s join public.task_items i on i.id = s.item_id
      join public.tasks t on t.id = i.task_id
      where s.next_transition_at <= pg_catalog.now() order by s.next_transition_at, s.item_id
      limit greatest(1, least(p_limit, 10000))
    loop
      perform 1 from public.projects where id = v_row.project_id for update skip locked;
      if not found then continue; end if;
      perform 1 from public.tasks where id = v_row.task_id for update skip locked;
      if not found then continue; end if;
      perform 1 from private.checklist_deadline_state where item_id = v_row.item_id
        and next_transition_at <= pg_catalog.now() for update skip locked;
      if not found then continue; end if;
      perform private.refresh_checklist_deadline(v_row.item_id);
      v_count := v_count + 1;
    end loop;
    return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION private.recalculate_task_status(p_task_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_status public.task_status;
begin
    perform 1 from public.tasks where id = p_task_id for update;
    v_status := private.task_status_from_items(p_task_id);
    update public.tasks set status = v_status, archived_at = null, archived_by_project_at = null
      where id = p_task_id and status <> 'archived' and status is distinct from v_status;
end;
$function$

CREATE OR REPLACE FUNCTION private.recalculate_task_status_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare v_task_id uuid := coalesce(new.task_id, old.task_id);
begin
  perform private.recalculate_task_status(v_task_id);
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.record_task_item_sync_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_item public.task_items%rowtype;
    v_project_id uuid;
begin
    if tg_op = 'UPDATE' and new.percentage is not distinct from old.percentage
       and new.is_completed is not distinct from old.is_completed
       and new.comment is not distinct from old.comment
       and new.is_archived is not distinct from old.is_archived
       and new.sync_version is not distinct from old.sync_version then
        return new;
    end if;
    if tg_op = 'DELETE' then v_item := old; else v_item := new; end if;
    select project_id into v_project_id from public.tasks where id = v_item.task_id;
    -- A parent cascade is covered by the existing project/task cache denial path.
    if v_project_id is null then return null; end if;
    insert into private.task_item_sync_changes(project_id, task_id, task_item_id, change_type, item)
    values (v_project_id, v_item.task_id, v_item.id,
        case when tg_op = 'DELETE' then 'delete' else 'upsert' end,
        case when tg_op = 'DELETE' then null else pg_catalog.to_jsonb(new) end);
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_checklist_deadline(p_item_id uuid, p_now timestamp with time zone DEFAULT now(), p_actor uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_previous text;
    v_next text;
    v_deadline timestamptz;
    v_percentage integer;
    v_inactive boolean;
begin
    select state into v_previous from private.checklist_deadline_state where item_id = p_item_id for update;
    if not found then return; end if;
    -- Never take item/parent locks after a state lock: item mutations already
    -- hold their normal project -> task -> item locks before entering here.
    select i.deadline_at, i.percentage, i.is_archived or t.status = 'archived' or p.status <> 'active'
      into v_deadline, v_percentage, v_inactive from public.task_items i
      join public.tasks t on t.id = i.task_id join public.projects p on p.id = t.project_id
      where i.id = p_item_id;
    if not found then return; end if;
    v_next := private.checklist_deadline_status(v_deadline, v_percentage, v_inactive, p_now);
    update private.checklist_deadline_state set state = v_next,
      next_transition_at = case v_next when 'normal' then v_deadline - interval '12 hours'
        when 'urgent' then v_deadline else null end where item_id = p_item_id;
    if v_previous is distinct from v_next then
      if v_next in ('urgent', 'overdue') then
        perform private.emit_checklist_deadline_event(p_item_id,
          case when v_previous = 'completed' then 'reopened_' || v_next else v_next end, v_deadline, p_actor);
      elsif v_next = 'completed' and v_previous in ('urgent', 'overdue') then
        perform private.emit_checklist_deadline_event(p_item_id, 'completed', v_deadline, p_actor);
      end if;
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_parent_checklist_deadlines()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
    if (old.status::text = 'archived') = (new.status::text = 'archived') then return new; end if;
    for v_id in select i.id from public.task_items i join public.tasks t on t.id = i.task_id
      where i.deadline_at is not null and
        ((tg_table_name = 'tasks' and t.id = new.id) or (tg_table_name = 'projects' and t.project_id = new.id))
      order by i.id
    loop
      perform private.refresh_checklist_deadline(v_id, pg_catalog.now(), auth.uid());
    end loop;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_task_item_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.is_completed := new.percentage = 100;
  elsif new.percentage is distinct from old.percentage then
    new.is_completed := new.percentage = 100;
  elsif new.is_completed is distinct from old.is_completed then
    new.percentage := case when new.is_completed then 100 else 0 end;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_item_action_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if new.project_id is null or new.task_id is null or new.task_item_id is null then
        raise exception 'item_actions historical identifiers must not be null'
            using errcode = 'not_null_violation';
    end if;
    if not exists (
        select 1 from public.tasks t
        where t.id = new.task_id and t.project_id = new.project_id
    ) then
        raise exception 'item_actions task/project mismatch'
            using errcode = 'foreign_key_violation';
    end if;
    if not exists (
        select 1 from public.task_items ti
        where ti.id = new.task_item_id and ti.task_id = new.task_id
    ) then
        raise exception 'item_actions item/task mismatch'
            using errcode = 'foreign_key_violation';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_project_member(p_project_id uuid, p_user_id uuid, p_role project_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_actor uuid := private.require_auth();
    v_project public.projects%rowtype;
    v_actor_role public.project_role;
begin
    v_project := private.lock_project_state(p_project_id);
    v_actor_role := private.lock_project_role(p_project_id, v_actor);
    if v_actor_role is null or v_actor_role not in ('owner', 'admin') then
        raise exception 'only owner/admin can manage project members'
            using errcode = 'insufficient_privilege';
    end if;
    if p_role = 'owner' then
        raise exception 'use transfer_project_ownership to set a new owner';
    end if;
    if p_role = 'admin' and v_actor_role <> 'owner' then
        raise exception 'only the owner can add an admin'
            using errcode = 'insufficient_privilege';
    end if;
    if v_project.status <> 'active' then
        raise exception 'project is archived';
    end if;
    if not exists (select 1 from auth.users where id = p_user_id) then
        raise exception 'user not found';
    end if;
    if exists (
        select 1 from public.project_members
         where project_id = p_project_id and user_id = p_user_id
    ) then
        raise exception 'user is already a project member';
    end if;

    insert into public.project_members(project_id, user_id, role)
    values (p_project_id, p_user_id, p_role);
    insert into public.task_members(task_id, user_id, set_by, set_at, role_override)
    select t.id, p_user_id, v_actor, now(), null
      from public.tasks t
     where t.project_id = p_project_id
    on conflict (task_id, user_id) do nothing;
    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, new_data)
    values (
        p_project_id,
        v_actor,
        'member_added',
        'project_member',
        p_user_id,
        jsonb_build_object('user_id', p_user_id, 'role', p_role)
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.add_project_member_by_identifier(p_project_id uuid, p_identifier text, p_role project_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_actor uuid := private.require_auth();
    v_project public.projects%rowtype;
    v_actor_role public.project_role;
    v_identifier text := btrim(coalesce(p_identifier, ''));
    v_target uuid;
    v_count integer;
begin
    v_project := private.lock_project_state(p_project_id);
    v_actor_role := private.lock_project_role(p_project_id, v_actor);
    if v_actor_role is null or v_actor_role not in ('owner', 'admin') then
        raise exception 'only owner/admin can manage project members'
            using errcode = 'insufficient_privilege';
    end if;
    if p_role = 'owner' then
        raise exception 'use transfer_project_ownership to set a new owner';
    end if;
    if p_role = 'admin' and v_actor_role <> 'owner' then
        raise exception 'only the owner can add an admin'
            using errcode = 'insufficient_privilege';
    end if;
    if v_project.status <> 'active' then
        raise exception 'project is archived';
    end if;
    if v_identifier = '' then
        raise exception 'identifier is required';
    end if;

    select count(*), (array_agg(id order by id))[1]
      into v_count, v_target
      from auth.users
     where email = lower(v_identifier);

    if v_count = 0 then
        select count(*), (array_agg(id order by id))[1]
          into v_count, v_target
          from public.profiles
         where display_name = v_identifier;
        if v_count > 1 then
            raise exception 'display name is ambiguous';
        end if;
    elsif v_count > 1 then
        raise exception 'email is ambiguous';
    end if;

    if v_count = 0 or v_target is null then
        raise exception 'user not found';
    end if;
    if exists (
        select 1 from public.project_members
         where project_id = p_project_id and user_id = v_target
    ) then
        raise exception 'user is already a project member';
    end if;

    insert into public.project_members(project_id, user_id, role)
    values (p_project_id, v_target, p_role);
    insert into public.task_members(task_id, user_id, set_by, set_at, role_override)
    select t.id, v_target, v_actor, now(), null
      from public.tasks t
     where t.project_id = p_project_id
    on conflict (task_id, user_id) do nothing;
    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, new_data)
    values (
        p_project_id,
        v_actor,
        'member_added',
        'project_member',
        v_target,
        jsonb_build_object('user_id', v_target, 'role', p_role)
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.add_task_assignee(p_task_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_user uuid := private.require_auth();
    v_project_id uuid := private.task_project_id(p_task_id);
    v_project public.projects%rowtype;
    v_task public.tasks%rowtype;
    v_actor_role public.project_role;
    v_target_role public.project_role;
begin
    if v_project_id is null then raise exception 'task not found'; end if;
    v_project := private.lock_project_state(v_project_id);
    v_task := private.lock_task(p_task_id);
    v_actor_role := private.lock_project_role(v_project_id, v_user);
    v_target_role := private.lock_project_role(v_project_id, p_user_id);
    if v_actor_role is null or v_actor_role not in ('owner', 'admin') then
        raise exception 'only owner/admin can manage assignees'
            using errcode = 'insufficient_privilege';
    end if;
    if v_task.status = 'archived' or v_project.status <> 'active' then
        raise exception 'task is archived';
    end if;
    if v_target_role is null then
        raise exception 'assignee must be a project member';
    end if;
    if exists (
        select 1 from public.task_assignees
         where task_id = p_task_id and user_id = p_user_id
    ) then
        return;
    end if;

    insert into public.task_assignees(task_id, user_id, assigned_by)
    values (p_task_id, p_user_id, v_user);
    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, new_data)
    values (
        v_project_id,
        v_user,
        'assignee_added',
        'task_assignee',
        p_user_id,
        jsonb_build_object('task_id', p_task_id, 'user_id', p_user_id)
    );
end;
$function$

