CREATE OR REPLACE FUNCTION public.hard_delete_task(p_task_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_user uuid := private.require_auth();
