CREATE OR REPLACE FUNCTION public.move_task(p_task_id uuid, p_direction integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_user uuid := private.require_auth();
    v_project_id uuid := private.task_project_id(p_task_id);
    v_project public.projects%rowtype;
    v_role public.project_role;
    v_task public.tasks%rowtype;
    v_neighbor public.tasks%rowtype;
begin
    if p_direction not in (-1, 1) then
        raise exception 'direction must be -1 or 1';
    end if;
    if v_project_id is null then raise exception 'task not found'; end if;

    v_project := private.lock_project_state(v_project_id);
    v_task := private.lock_task(p_task_id);
    v_role := private.lock_project_role(v_project_id, v_user);
    if v_role is null or v_role not in ('owner', 'admin') then
        raise exception 'only owner/admin can reorder stages'
            using errcode = 'insufficient_privilege';
    end if;
    if v_task.status = 'archived' or v_project.status <> 'active' then
        raise exception 'task is archived';
    end if;

    if p_direction = -1 then
        select * into v_neighbor
          from public.tasks t
         where t.project_id = v_project_id
           and t.status <> 'archived'
           and (t.position, t.created_at, t.id) < (v_task.position, v_task.created_at, v_task.id)
         order by t.position desc, t.created_at desc, t.id desc
         limit 1
         for update;
    else
        select * into v_neighbor
          from public.tasks t
         where t.project_id = v_project_id
           and t.status <> 'archived'
           and (t.position, t.created_at, t.id) > (v_task.position, v_task.created_at, v_task.id)
         order by t.position asc, t.created_at asc, t.id asc
         limit 1
         for update;
    end if;
    if not found then return; end if;

    update public.tasks
       set position = case
           when id = v_task.id then v_neighbor.position
           when id = v_neighbor.id then v_task.position
           else position
       end
     where id in (v_task.id, v_neighbor.id);
    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, old_data, new_data)
    values
        (v_project_id, v_user, 'reordered', 'task', v_task.id,
         jsonb_build_object('position', v_task.position),
         jsonb_build_object('position', v_neighbor.position)),
        (v_project_id, v_user, 'reordered', 'task', v_neighbor.id,
         jsonb_build_object('position', v_neighbor.position),
         jsonb_build_object('position', v_task.position));
end;
$function$

CREATE OR REPLACE FUNCTION public.move_task_template_item(p_item_id uuid, p_direction integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_user uuid := private.require_auth();
    v_template_id uuid;
    v_template public.task_templates%rowtype;
    v_item public.task_template_items%rowtype;
    v_neighbor public.task_template_items%rowtype;
begin
    if p_direction not in (-1, 1) then
        raise exception 'direction must be -1 or 1';
    end if;

    select template_id into v_template_id
      from public.task_template_items
     where id = p_item_id;
    if not found then
        raise exception 'template item not found';
    end if;

    select * into v_template
      from public.task_templates
     where id = v_template_id
     for update;

    select * into v_item
      from public.task_template_items
     where id = p_item_id
     for update;

    if not found or v_item.template_id <> v_template_id then
        raise exception 'template item not found';
    end if;
    if v_template.archived_at is not null or v_template.created_by <> v_user then
        raise exception 'no permission to reorder template item'
            using errcode = 'insufficient_privilege';
    end if;

    if p_direction = -1 then
        select * into v_neighbor
          from public.task_template_items i
         where i.template_id = v_template_id
           and (i.position, i.created_at, i.id)
               < (v_item.position, v_item.created_at, v_item.id)
         order by i.position desc, i.created_at desc, i.id desc
         limit 1
         for update;
    else
        select * into v_neighbor
          from public.task_template_items i
         where i.template_id = v_template_id
           and (i.position, i.created_at, i.id)
               > (v_item.position, v_item.created_at, v_item.id)
         order by i.position asc, i.created_at asc, i.id asc
         limit 1
         for update;
    end if;

    if not found then
        return;
    end if;

    -- Reuse the compatibility-safe swap path without sending stale text.
    perform public.update_task_template_item(
        p_item_id,
        null,
        null,
        v_neighbor.position
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.pull_task_item_changes(p_after_cursor bigint, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := private.require_auth();
    v_rows jsonb;
    v_cursor bigint;
    v_count integer;
    v_floor bigint;
begin
    if p_after_cursor is null or p_after_cursor < 0 or p_limit is null or p_limit < 1 or p_limit > 500 then
        raise exception 'invalid sync cursor or page size' using errcode = '22023';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(29175, 5);
    select retained_after_cursor into v_floor from private.task_item_sync_retention where singleton;
    if p_after_cursor < v_floor then
        raise exception 'task item sync cursor expired; reset required' using errcode = 'P0001';
    end if;
    with page as materialized (
        select cursor, task_id, task_item_id, change_type, item
          from private.task_item_sync_changes
         where cursor > p_after_cursor order by cursor limit p_limit
    ), visible as (
        select cursor, task_id, task_item_id, change_type, item from page
         where private.has_task_access(task_id, v_user)
    )
    select coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
             'cursor', cursor, 'task_id', task_id, 'task_item_id', task_item_id,
             'change_type', change_type, 'item', item) order by cursor) from visible), '[]'::jsonb),
           coalesce((select max(cursor) from page), p_after_cursor),
           (select count(*) from page)
      into v_rows, v_cursor, v_count;
    return pg_catalog.jsonb_build_object('changes', v_rows, 'next_cursor', v_cursor, 'has_more', v_count = p_limit);
end;
$function$

CREATE OR REPLACE FUNCTION public.pull_task_item_changes_v2(p_after_cursor bigint, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_floor bigint;
begin
    perform private.require_auth();
    if p_after_cursor is null or p_after_cursor < 0 or p_limit is null or p_limit < 1 or p_limit > 500 then
        raise exception 'invalid sync cursor or page size' using errcode = '22023';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(29175, 5);
    select retained_after_cursor into v_floor from private.task_item_sync_retention where singleton;
    if p_after_cursor < v_floor then
        return pg_catalog.jsonb_build_object('reset_required', true, 'retained_after_cursor', v_floor);
    end if;
    return public.pull_task_item_changes(p_after_cursor, p_limit);
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_project_member(p_project_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_actor uuid := private.require_auth();
    v_project public.projects%rowtype;
    v_actor_role public.project_role;
    v_target_role public.project_role;
begin
    v_project := private.lock_project_state(p_project_id);
    v_actor_role := private.lock_project_role(p_project_id, v_actor);
    v_target_role := private.lock_project_role(p_project_id, p_user_id);
    if v_actor_role is null or v_actor_role not in ('owner', 'admin') then
        raise exception 'only owner/admin can manage project members'
            using errcode = 'insufficient_privilege';
    end if;
    if v_project.status <> 'active' then
        raise exception 'project is archived';
    end if;
    if v_target_role is null then
        return;
    end if;
    if v_target_role = 'owner' then
        raise exception 'cannot remove the project owner - transfer ownership first';
    end if;
    if v_target_role = 'admin' and v_actor_role <> 'owner' then
        raise exception 'only the owner can remove an administrator'
            using errcode = 'insufficient_privilege';
    end if;

    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, new_data)
    select p_project_id,
           v_actor,
           'assignee_removed'::public.audit_action,
           'task_assignee',
           ta.user_id,
           jsonb_build_object(
               'task_id', ta.task_id,
               'user_id', ta.user_id,
               'reason', 'project membership removed'
           )
      from public.task_assignees ta
      join public.tasks t on t.id = ta.task_id
     where t.project_id = p_project_id
       and ta.user_id = p_user_id;

    delete from public.task_assignees ta
     using public.tasks t
     where ta.task_id = t.id
       and t.project_id = p_project_id
       and ta.user_id = p_user_id;
    delete from public.task_members tm
     using public.tasks t
     where tm.task_id = t.id
       and t.project_id = p_project_id
       and tm.user_id = p_user_id;
    delete from public.project_members
     where project_id = p_project_id and user_id = p_user_id;

    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, old_data)
    values (
        p_project_id,
        v_actor,
        'member_removed',
        'project_member',
        p_user_id,
        jsonb_build_object('user_id', p_user_id, 'role', v_target_role)
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_task_assignee(p_task_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_user uuid := private.require_auth();
    v_project_id uuid := private.task_project_id(p_task_id);
    v_project public.projects%rowtype;
    v_task public.tasks%rowtype;
    v_actor_role public.project_role;
begin
    if v_project_id is null then raise exception 'task not found'; end if;
    v_project := private.lock_project_state(v_project_id);
    v_task := private.lock_task(p_task_id);
    v_actor_role := private.lock_project_role(v_project_id, v_user);
    if v_actor_role is null or v_actor_role not in ('owner', 'admin') then
        raise exception 'only owner/admin can manage assignees'
            using errcode = 'insufficient_privilege';
    end if;
    if v_task.status = 'archived' or v_project.status <> 'active' then
        raise exception 'task is archived';
    end if;
    if not exists (
        select 1 from public.task_assignees
         where task_id = p_task_id and user_id = p_user_id
    ) then
        return;
    end if;

    delete from public.task_assignees
     where task_id = p_task_id and user_id = p_user_id;
    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, new_data)
    values (
        v_project_id,
        v_user,
        'assignee_removed',
        'task_assignee',
        p_user_id,
        jsonb_build_object('task_id', p_task_id, 'user_id', p_user_id)
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_project(p_project_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare
    v_user uuid := private.require_auth();
    v_project public.projects%rowtype;
    v_role public.project_role;
begin
    v_project := private.lock_project_state(p_project_id);
    v_role := private.lock_project_role(p_project_id, v_user);
    if v_role is null or v_role not in ('owner', 'admin') then
        raise exception 'project admin role required' using errcode = 'insufficient_privilege';
    end if;
    if v_project.status <> 'archived' then
        raise exception 'project is not archived';
    end if;

    update public.projects set status = 'active', archived_at = null where id = p_project_id;
    update public.tasks t
       set status = private.task_status_from_items(t.id),
           archived_at = null,
           archived_by_project_at = null
     where t.project_id = p_project_id
       and t.status = 'archived'
       and t.archived_by_project_at = v_project.archived_at;
    insert into public.audit_log(project_id, user_id, action, entity_type, entity_id, old_data, new_data)
    values (
        p_project_id,
        v_user,
        'restored',
        'project',
        p_project_id,
        jsonb_build_object('status', v_project.status, 'archived_at', v_project.archived_at),
        jsonb_build_object('status', 'active', 'archived_at', null)
    );
end;
$function$

